package main

import (
	"context"
	"fmt"
	"os"

	sdk "warp-hr"
	"warp-hr/option"
)

func main() {
	client := sdk.NewClient(
		option.WithAPIKey(os.Getenv("API_KEY")),
	)

	worker, err := client.Workers.Invite(context.Background(), "wrk_1234")
	if err != nil {
		panic(err)
	}
	fmt.Println(worker)
}

